from pathlib import Path
p=Path('src/components/client-connections.tsx');s=p.read_text(encoding='utf-8-sig');s=s.replace('name:string;email:string;marketplace:string','name?:string;clientCode?:string;email:string;marketplace:string');s=s.replace("[name,setName]=useState('')","[clientCode,setClientCode]=useState('')");s=s.replace("setName('')","setClientCode('')");s=s.replace('<strong>{connection.name}</strong>','<strong>{connection.name||`Клиент ${connection.clientCode}`}</strong>');s=s.replace('connections.some(item=>item.email===normalized&&item.marketplace===marketplace)','connections.some(item=>item.clientCode===clientCode.trim()&&item.marketplace===marketplace)');s=s.replace('name:name.trim(),email:normalized','clientCode:clientCode.trim(),email:normalized');s=s.replace('htmlFor="client-name">Название кабинета','htmlFor="client-code">Индивидуальный код клиента');s=s.replace('id="client-name" required value={name} onChange={event=>setName(event.target.value)}','id="client-code" required autoComplete="off" value={clientCode} onChange={event=>setClientCode(event.target.value)}');s=s.replace('disabled={!name.trim()||!email.trim()}','disabled={!clientCode.trim()||!email.trim()}');p.write_text(s,encoding='utf-8')
